$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$root='C:\JudasValidation';$base='http://192.168.122.1:8872';$out="$root\M78ContinuationResults";$label='diagnostic-warm-v1';$owned="$out\$label";$on="$owned\warm-on";$off="$owned\warm-off";$env:GALLIUM_DRIVER='llvmpipe';$env:JUDAS_ENGINE_ROOT="$root\Source"
function Upload($p,$n){Invoke-WebRequest -UseBasicParsing "$base/$n" -Method Post -InFile $p|Out-Null}
try{
 $compiled=Get-Content "$out\m78-$label-warm_observer.json" -Raw|ConvertFrom-Json;if($compiled.exitCode -ne 0){throw 'Original write acceptance failed'};if(Test-Path $off){throw 'Preserve previous warm-seed isolation'}
 $env:JUDAS_DIAGNOSTIC_CONTINUE_WRITE='1';$env:JUDAS_DIAGNOSTIC_WARM_SEEDS_OFF='1';Remove-Item Env:\JUDAS_DIAGNOSTIC_RESTORE_DRIVES -ErrorAction SilentlyContinue
 & "$root\M78ContinuationSource\Scripts\v6\windows_direct_run.ps1" -ManifestName 'm78-continuation-direct-diagnostic-warm-v1.json' -CaseId 'warm_observer' -RunId 'warm-off' -Arguments @($off,'cold-write')
 $onSHA=(Get-FileHash "$on\slots\m77.save").Hash.ToLower();$offSHA=(Get-FileHash "$off\slots\m77.save").Hash.ToLower();$files=@()
 foreach($name in @('warm-on','warm-off')){foreach($f in Get-ChildItem -LiteralPath "$owned\$name" -File){$n="m78-$label-$name-"+$f.Name;if($f.Length -gt 16777216){throw 'Unexpected large diagnostic artifact'};Upload $f.FullName $n;$files+=@{name=$n;bytes=$f.Length;sha256=(Get-FileHash $f.FullName).Hash.ToLower()}};Upload "$owned\$name\slots\m77.save" "m78-$label-$name-m77.save"}
 $p="$out\m78-$label-isolation.json";@{scope='Copied numerical mechanism isolation only. Original saved boundary/input/timestep/acceptance unchanged. ON retains source warm seeds; OFF suppresses only first next completed-solve seeds; actual commands, clocks, geometry eligibility/completed observations remain. No production edits or retained runtime change.';sameSaveBytes=($onSHA -eq $offSHA);onSaveSHA256=$onSHA;offSaveSHA256=$offSHA;baselineArchiveSHA256='791edc06d69e9a0c750c2bf23f91b20936ed5c0d530f20a936eed0c544c9ba48';diagnosticArchiveSHA256=$compiled.archiveSHA256;sourceSHA256=$compiled.compiles[0].sourceSHA256;files=$files;freeBytes=(Get-PSDrive C).Free}|ConvertTo-Json -Depth 7|Set-Content $p -Encoding UTF8;Upload $p ([IO.Path]::GetFileName($p));if($onSHA -ne $offSHA){throw 'Snapshot byte identity differs; no causal equivalent-input claim permitted'}
}catch{$p="$out\m78-$label-isolation-error.txt";[string]$_.Exception.Message|Set-Content $p;Upload $p ([IO.Path]::GetFileName($p));exit 1}
